import Foundation

public enum UIDGenerator {
    /// Root for UIDs generated by Specula (UUID-derived 2.25 form, globally unique without registration).
    public static func make() -> String {
        let u = UUID().uuid
        var hi: UInt64 = 0, lo: UInt64 = 0
        withUnsafeBytes(of: u) { raw in
            for i in 0..<8 { hi = hi << 8 | UInt64(raw[i]) }
            for i in 8..<16 { lo = lo << 8 | UInt64(raw[i]) }
        }
        return "2.25." + decimal128(hi: hi, lo: lo)
    }

    /// Deterministic UID derived from an input string (used for consistent anonymisation).
    public static func derived(from s: String, salt: String) -> String {
        var h1: UInt64 = 0xcbf2_9ce4_8422_2325, h2: UInt64 = 0x8422_2325_cbf2_9ce4
        for b in (salt + "|" + s).utf8 {
            h1 = (h1 ^ UInt64(b)) &* 0x100_0000_01b3
            h2 = (h2 ^ UInt64(b)) &* 0x100_0000_01b3 &+ 0x9e37_79b9
        }
        return "2.25." + decimal128(hi: h1 & 0x7FFF_FFFF_FFFF_FFFF, lo: h2)
    }

    static func decimal128(hi: UInt64, lo: UInt64) -> String {
        // Repeated division of a 128-bit number by 10.
        var h = hi, l = lo
        var digits: [Character] = []
        if h == 0 && l == 0 { return "0" }
        while h != 0 || l != 0 {
            let (qh, rh) = h.quotientAndRemainder(dividingBy: 10)
            let (ql, rl) = (UInt64(10).dividingFullWidth((rh, l)))
            h = qh; l = ql
            digits.append(Character(String(rl)))
        }
        return String(digits.reversed())
    }

    public static let implementationClassUID = derived(from: "Specula DICOM Viewer implementation", salt: "1")
    public static let implementationVersionName = "SPECULA_10"
}

/// Serialises data sets in a given transfer syntax.
public enum DICOMWriter {
    public static func encode(_ ds: DataSet, transferSyntax ts: TransferSyntax) -> Data {
        var out = Data()
        out.reserveCapacity(1 << 16)
        write(ds, into: &out, explicit: ts.explicitVR, be: ts.bigEndian)
        if ts.deflated, let d = Inflate.deflate(out) { return d }
        return out
    }

    /// Complete Part 10 file with preamble and file meta information.
    public static func fileData(_ ds: DataSet, transferSyntax ts: TransferSyntax, sourceAE: String? = nil) -> Data {
        var out = fileHeader(sopClassUID: ds.string(.sopClassUID) ?? "1.2.840.10008.5.1.4.1.1.7",
                             sopInstanceUID: ds.string(.sopInstanceUID) ?? UIDGenerator.make(),
                             transferSyntaxUID: ts.uid, sourceAE: sourceAE)
        // Data set without group 0002
        let body = DataSet(bigEndian: ds.bigEndian)
        for e in ds.sortedElements where e.tag.group != 0x0002 { body.insert(e) }
        out.append(encode(body, transferSyntax: ts))
        return out
    }

    /// Preamble, "DICM" and file meta group; append an already-encoded data set to make a Part 10 file.
    public static func fileHeader(sopClassUID: String, sopInstanceUID: String, transferSyntaxUID: String, sourceAE: String? = nil) -> Data {
        let meta = DataSet()
        meta.set(.fileMetaInformationVersion, .OB, data: Data([0x00, 0x01]))
        meta.set(.mediaStorageSOPClassUID, .UI, string: sopClassUID)
        meta.set(.mediaStorageSOPInstanceUID, .UI, string: sopInstanceUID)
        meta.set(.transferSyntaxUID, .UI, string: transferSyntaxUID)
        meta.set(.implementationClassUID, .UI, string: UIDGenerator.implementationClassUID)
        meta.set(.implementationVersionName, .SH, string: UIDGenerator.implementationVersionName)
        if let ae = sourceAE, !ae.isEmpty { meta.set(.sourceApplicationEntityTitle, .AE, string: ae) }
        var metaBody = Data()
        write(meta, into: &metaBody, explicit: true, be: false)
        var out = Data(count: 128)
        out.append(contentsOf: [0x44, 0x49, 0x43, 0x4D])
        appendTagLE(&out, .fileMetaInformationGroupLength)
        out.append(contentsOf: [0x55, 0x4C, 0x04, 0x00])
        appendU32(&out, UInt32(metaBody.count), be: false)
        out.append(metaBody)
        return out
    }

    static func appendTagLE(_ out: inout Data, _ t: Tag) {
        appendU16(&out, t.group, be: false); appendU16(&out, t.element, be: false)
    }

    @inline(__always) static func appendU16(_ out: inout Data, _ v: UInt16, be: Bool) {
        let x = be ? v.byteSwapped : v
        withUnsafeBytes(of: x) { out.append(contentsOf: $0) }
    }

    @inline(__always) static func appendU32(_ out: inout Data, _ v: UInt32, be: Bool) {
        let x = be ? v.byteSwapped : v
        withUnsafeBytes(of: x) { out.append(contentsOf: $0) }
    }

    static func write(_ ds: DataSet, into out: inout Data, explicit: Bool, be: Bool) {
        for e in ds.sortedElements {
            if e.tag.isGroupLength && e.tag.group != 0x0002 { continue } // group lengths are optional and often stale
            writeElement(e, owner: ds, into: &out, explicit: explicit, be: be)
        }
    }

    static func swapped(_ d: Data, size: Int) -> Data {
        guard size > 1 else { return d }
        var out = Data(count: d.count - d.count % size)
        out.withUnsafeMutableBytes { (dst: UnsafeMutableRawBufferPointer) in
            d.withUnsafeBytes { (src: UnsafeRawBufferPointer) in
                var i = 0
                while i + size <= src.count {
                    for k in 0..<size { dst[i + k] = src[i + size - 1 - k] }
                    i += size
                }
            }
        }
        return out
    }

    static func writeHeader(_ tag: Tag, _ vr: VR, length: UInt32, into out: inout Data, explicit: Bool, be: Bool) {
        appendU16(&out, tag.group, be: be)
        appendU16(&out, tag.element, be: be)
        if explicit {
            out.append(contentsOf: Array(vr.rawValue.utf8))
            if vr.hasLongExplicitLength {
                out.append(contentsOf: [0, 0])
                appendU32(&out, length, be: be)
            } else {
                appendU16(&out, UInt16(truncatingIfNeeded: length), be: be)
            }
        } else {
            appendU32(&out, length, be: be)
        }
    }

    static func writeElement(_ e: DataElement, owner: DataSet, into out: inout Data, explicit: Bool, be: Bool) {
        switch e.value {
        case .sequence(let items):
            writeHeader(e.tag, .SQ, length: 0xFFFF_FFFF, into: &out, explicit: explicit, be: be)
            for item in items {
                appendU16(&out, 0xFFFE, be: be); appendU16(&out, 0xE000, be: be); appendU32(&out, 0xFFFF_FFFF, be: be)
                write(item, into: &out, explicit: explicit, be: be)
                appendU16(&out, 0xFFFE, be: be); appendU16(&out, 0xE00D, be: be); appendU32(&out, 0, be: be)
            }
            appendU16(&out, 0xFFFE, be: be); appendU16(&out, 0xE0DD, be: be); appendU32(&out, 0, be: be)
        case .encapsulated(let enc):
            writeHeader(e.tag, .OB, length: 0xFFFF_FFFF, into: &out, explicit: explicit, be: be)
            appendU16(&out, 0xFFFE, be: be); appendU16(&out, 0xE000, be: be); appendU32(&out, UInt32(enc.basicOffsetTable.count), be: be)
            out.append(enc.basicOffsetTable)
            for f in enc.fragments {
                var frag = f
                if frag.count % 2 == 1 { frag.append(0) }
                appendU16(&out, 0xFFFE, be: be); appendU16(&out, 0xE000, be: be); appendU32(&out, UInt32(frag.count), be: be)
                out.append(frag)
            }
            appendU16(&out, 0xFFFE, be: be); appendU16(&out, 0xE0DD, be: be); appendU32(&out, 0, be: be)
        case .data(var d):
            var vr = e.vr
            if !explicit && vr == .UN { vr = DataDictionary.vr(for: e.tag) }
            if owner.bigEndian != be, let size = e.vr.binaryValueSize, size > 1 {
                d = swapped(d, size: size)
            }
            if d.count % 2 == 1 { d.append(vr.paddingByte) }
            if explicit && !vr.hasLongExplicitLength && d.count > 0xFFFF {
                vr = .UN // too long for 16-bit length field
            }
            writeHeader(e.tag, vr, length: UInt32(d.count), into: &out, explicit: explicit, be: be)
            out.append(d)
        }
    }
}
